                self.generated += 1
                outputs = yield from self._output_events(expr)
                self.meter.charge("exact_work_units")
                yield None
                if not self.quotient or self.dag.retain(expr, self.scope, outputs, size):
                    self.pool[(size, expr.sort)].append(expr)
                    self.retained += 1
